import React, { useEffect, useRef, useCallback } from "react";

const WMO_EMOJI = {
  Clear: "☀️",
  Clouds: "☁️",
  Rain: "🌧️",
  Drizzle: "🌦️",
  Thunderstorm: "⛈️",
  Snow: "❄️",
  Mist: "🌫️",
};

export default function WeatherMap({ weather, onCityChange }) {
  const mapRef = useRef(null);
  const mapInstanceRef = useRef(null);
  const markerRef = useRef(null);

  const reverseGeocode = useCallback(async (lat, lon) => {
    try {
      const res = await fetch(
        `https://nominatim.openstreetmap.org/reverse?lat=${lat}&lon=${lon}&format=json&accept-language=ru`
      );
      const data = await res.json();
      const addr = data.address || {};
      return addr.city || addr.town || addr.village || addr.county || addr.state || null;
    } catch {
      return null;
    }
  }, []);

  useEffect(() => {
    const L = window.L;

    if (!L || !mapRef.current || mapInstanceRef.current) return;

    const map = L.map(mapRef.current, {
      center: [55.75, 37.62],
      zoom: 5,
      zoomControl: true,
    });

    L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
      attribution: "© OpenStreetMap",
      maxZoom: 19,
    }).addTo(map);

    map.on("click", async (e) => {
      const cityName = await reverseGeocode(e.latlng.lat, e.latlng.lng);
      if (cityName) onCityChange(cityName);
    });

    mapInstanceRef.current = map;

    setTimeout(() => {
      map.invalidateSize();
    }, 300);

    return () => {
      map.remove();
      mapInstanceRef.current = null;
    };
  }, [reverseGeocode, onCityChange]);

  useEffect(() => {
    const L = window.L;
    const map = mapInstanceRef.current;

    if (!L || !map || !weather) return;

    fetch(
      `https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(
        weather.city
      )}&count=1`
    )
      .then((r) => r.json())
      .then((data) => {
        const result = data.results?.[0];
        if (!result) return;

        const lat = result.latitude;
        const lon = result.longitude;

        if (markerRef.current) {
          markerRef.current.remove();
        }

        const emoji = WMO_EMOJI[weather.weather_main] || "🌤️";

        const icon = L.divIcon({
          className: "",
          html: `
            <div class="map-marker">
              <div class="map-marker-bubble">
                <span class="map-marker-emoji">${emoji}</span>
                <span class="map-marker-temp">${weather.temp}°</span>
              </div>
              <div class="map-marker-city">${weather.city}</div>
              <div class="map-marker-pin"></div>
            </div>
          `,
          iconAnchor: [50, 80],
          iconSize: [100, 80],
        });

        markerRef.current = L.marker([lat, lon], { icon })
          .addTo(map)
          .bindPopup(`${emoji} ${weather.city}: ${weather.temp}°C`)
          .openPopup();

        map.flyTo([lat, lon], 8, { duration: 1.2 });

        setTimeout(() => {
          map.invalidateSize();
        }, 300);
      });
  }, [weather]);

  return (
    <div className="glass-card map-section">
      <h2 className="section-title">🗺️ Карта</h2>
      <p className="map-hint">
        Кликни по карте чтобы посмотреть погоду в любом месте
      </p>
      <div ref={mapRef} className="map-container" />
    </div>
  );
}
